import React, { useState, useEffect, useMemo } from 'react';
import { FaTrash, FaPen } from 'react-icons/fa';

// --- Helper Components for Icons ---
const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16" style={{ marginLeft: '8px', color: '#6c757d', cursor: 'pointer' }}>
        <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z"/>
        <path d="m8.93 6.588-2.29.287-.082.38.45.083c.294.07.352.176.288.469l-.738 3.468c-.064.293.006.399.287.47l.45.083.082-.38-2.29-.287a.5.5 0 0 1-.45-.635l.733-3.468a.5.5 0 0 1 .636-.45l2.29.287z"/>
        <path d="M8 4.5a1 1 0 1 1-2 0 1 1 0 0 1 2 0z"/>
    </svg>
);


export default function PerDeliveryAllocationTab({ term, onAllocationChange }) {
    // --- State Management ---
    const [firstOffering, setFirstOffering] = useState('Yes');
    const [deliveries, setDeliveries] = useState([
        { id: 1, location: 'CTN', lecturer: 'Mary', weeklyHours: 2, earlyCareer: 'No' },
        { id: 2, location: 'PEN', lecturer: 'Mary', weeklyHours: 0, earlyCareer: 'No' },
        { id: 3, location: 'KWD', lecturer: 'Mary', weeklyHours: 0, earlyCareer: 'No' },
    ]);
    const [totalAllocation, setTotalAllocation] = useState(0);

    // --- Calculation Logic ---
    const termMultiplier = useMemo(() => (term === 'Autumn' ? 1.0 : 0.923), [term]);

    useEffect(() => {
        // Step 1 & 2: Calculate allocation for each delivery and early career bonus
        const earlyCareerBonusMap = {
            "Yes - materials provided": 0.02,
            "Yes - materials need major rewriting": 0.03,
            "Yes - no materials provided": 0.04,
        };

        const deliveriesWithAllocation = deliveries.map(d => {
            const earlyCareerBonus = earlyCareerBonusMap[d.earlyCareer] || 0;
            const allocation = 0.01 + (d.weeklyHours * termMultiplier * 0.01) + earlyCareerBonus;
            return { ...d, allocation };
        });

        // Step 3: Sum individual allocations
        const sumOfIndividualAllocations = deliveriesWithAllocation.reduce((sum, d) => sum + d.allocation, 0);

        // Step 4: Calculate first offering bonus
        let firstOfferingBonus = 0;
        if (firstOffering === 'Yes' && deliveries.length > 0) {
            const maxWeeklyHours = Math.max(...deliveries.map(d => d.weeklyHours));
            firstOfferingBonus = 0.01 * termMultiplier * maxWeeklyHours;
        }

        // Step 5: Calculate final total
        const finalTotal = sumOfIndividualAllocations + firstOfferingBonus;
        setTotalAllocation(finalTotal);

        // Optional: Lift state up to parent component
        if (onAllocationChange) {
            onAllocationChange(finalTotal);
        }

    }, [deliveries, firstOffering, termMultiplier, onAllocationChange]);


    // --- Handlers for UI interactions ---
    const handleAddDelivery = () => {
        const newId = deliveries.length > 0 ? Math.max(...deliveries.map(d => d.id)) + 1 : 1;
        setDeliveries([...deliveries, { id: newId, location: '', lecturer: '', weeklyHours: 0, earlyCareer: 'No' }]);
    };

    const handleRemoveDelivery = (id) => {
        setDeliveries(deliveries.filter(d => d.id !== id));
    };

    const handleDeliveryChange = (id, field, value) => {
        setDeliveries(deliveries.map(d => 
            d.id === id ? { ...d, [field]: (field === 'weeklyHours' ? Number(value) : value) } : d
        ));
    };

    // Calculate individual allocation for display in the table
    const getIndividualAllocation = (delivery) => {
        const earlyCareerBonusMap = {
            "Yes - materials provided": 0.02,
            "Yes - materials need major rewriting": 0.03,
            "Yes - no materials provided": 0.04,
        };
        const earlyCareerBonus = earlyCareerBonusMap[delivery.earlyCareer] || 0;
        return 0.01 + (delivery.weeklyHours * termMultiplier * 0.01) + earlyCareerBonus;
    };


    return (
        <div style={styles.container}>
            {/* --- Total Allocation Display --- */}
            <div style={styles.formGroup}>
                <label style={styles.label}>
                    Per-delivery Allocation
                    <InfoIcon />
                </label>
                <input 
                    type="text" 
                    value={`${(totalAllocation * 100).toFixed(1)}%`} 
                    readOnly 
                    style={styles.inputReadOnly} 
                />
            </div>

            {/* --- First Offering Selection --- */}
            <div style={styles.formGroup}>
                <label htmlFor="firstOffering" style={styles.label}>
                    First offering of the calendar year
                    <InfoIcon />
                </label>
                <select 
                    id="firstOffering"
                    value={firstOffering} 
                    onChange={(e) => setFirstOffering(e.target.value)} 
                    style={styles.select}
                >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                </select>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '1rem' }}>
                <button onClick={handleAddDelivery} style={styles.addButton}>+ Add</button>
            </div>

            {/* --- Deliveries Table --- */}
            <table style={styles.table}>
                <thead>
                    <tr>
                        <th style={styles.th}>Actions</th>
                        <th style={styles.th}>Delivery</th>
                        <th style={styles.th}>Lecturer / Campus Coordinator</th>
                        <th style={styles.th}>Weekly lecture time over 13 weeks (hours)</th>
                        <th style={styles.th}>Early career academic loading</th>
                        <th style={styles.th}>Allocation</th>
                    </tr>
                </thead>
                <tbody>
                    {deliveries.map(delivery => (
                        <tr key={delivery.id}>
                            <td style={styles.td}>
                                <button style={styles.iconButton}><FaPen /></button>
                                <button onClick={() => handleRemoveDelivery(delivery.id)} style={styles.iconButton}><FaTrash /></button>
                            </td>
                            <td style={styles.td}><input type="text" value={delivery.location} onChange={e => handleDeliveryChange(delivery.id, 'location', e.target.value)} style={styles.tableInput} /></td>
                            <td style={styles.td}><input type="text" value={delivery.lecturer} onChange={e => handleDeliveryChange(delivery.id, 'lecturer', e.target.value)} style={styles.tableInput} /></td>
                            <td style={styles.td}><input type="number" min="0" value={delivery.weeklyHours} onChange={e => handleDeliveryChange(delivery.id, 'weeklyHours', e.target.value)} style={styles.tableInput} /></td>
                            <td style={styles.td}>
                                <select value={delivery.earlyCareer} onChange={e => handleDeliveryChange(delivery.id, 'earlyCareer', e.target.value)} style={styles.tableSelect}>
                                    <option>No</option>
                                    <option>Yes - materials provided</option>
                                    <option>Yes - materials need major rewriting</option>
                                    <option>Yes - no materials provided</option>
                                </select>
                            </td>
                            <td style={styles.td}>
                                <input 
                                    type="text" 
                                    value={`${(getIndividualAllocation(delivery) * 100).toFixed(1)}%`}
                                    readOnly 
                                    style={{...styles.tableInput, ...styles.inputReadOnly, textAlign: 'right' }} 
                                />
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '1.5rem' }}>
                <button style={styles.saveButton}>Save</button>
            </div>
        </div>
    );
}

